{[Fact] public void PublicConstructorsAndJsonSeamHaveActiveConsumers(){string r=Read("HybridCPU_ISE","CloseToHSL","Core","Pipeline","MicroOps","Replay","ReplayToken.cs");string m=Read("HybridCPU_ISE","CloseToHSL","Core","Pipeline","MicroOps","Types","MicroOp.cs");string l=Read("HybridCPU_ISE","CloseToHSL","Core","Pipeline","MicroOps","Memory","MicroOp.LoadStore.cs");Assert.Contains("public ReplayToken()",r,StringComparison.Ordinal);Assert.Contains("public ReplayToken(YAKSys_Hybrid_CPU.Processor.MainMemoryArea? mainMemory)",r,StringComparison.Ordinal);Assert.Contains("JsonSerializer.Deserialize<ReplayToken>(json)",r,StringComparison.Ordinal);Assert.Contains("new HybridCPU_ISE.Core.ReplayToken(mainMemory)",m,StringComparison.Ordinal);Assert.Contains("new HybridCPU_ISE.Core.ReplayToken(mainMemory)",l,StringComparison.Ordinal);}private static string Read(params string[] p)=>File.ReadAllText(Path.Combine(new[]{Root()}.Concat(p).ToArray()));private static string Root(){DirectoryInfo? c=new(AppContext.BaseDirectory);while(c is not null){if(Directory.Exists(Path.Combine(c.FullName,"HybridCPU_ISE")))return c.FullName;c=c.Parent;}throw new DirectoryNotFoundException();}}
